import re
import os
from pathlib import Path
import glob


def task_func(
    directory_path: str, regex_pattern: str = r"\(.+?\)|\w"
) -> dict:
    directory = Path(directory_path)

    if not directory.is_dir():
        return {}

    results = {}

    for file_path in glob.glob(str(directory / "*.txt")):
        path = Path(file_path)

        if not path.is_file():
            continue

        try:
            content = path.read_text(encoding="utf-8")
        except (OSError, UnicodeError):
            continue

        results[path.name] = re.findall(regex_pattern, content)

    return results
